        d_OVA = torch.zeros_like(y[:, 0])
        d_O2VAD1 = torch.zeros_like(y[:, 0])
        alg_0_OSA = torch.zeros_like(y[:, 0])
        alg_1_PO2ART = torch.zeros_like(y[:, 0])
